<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {AlertCircle,Check,CheckCircle2,LoaderCircle,LockKeyhole,Plus,RefreshCw,ShieldCheck,Tag,Trash2,X} from 'lucide-vue-next';
import ApprovalReview from './ApprovalReview.vue';
import VariableRecovery from './VariableRecovery.vue';
import {createRequestGuard} from '../lib/async-response';
type Item=Record<string,any>;
type Override={id:string;agent:string;existing:boolean;replace:boolean;value:string};
const props=defineProps<{tenant:string;tenantName:string;resource?:Item|null;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{close:[];updated:[];saved:[key:string];notice:[message:string]}>();
const options=ref<Item|null>(null);const key=ref('');const description=ref('');const secret=ref(true);const replaceValue=ref(false);const value=ref('');const overrides=ref<Override[]>([]);const review=ref<Item|null>(null);const prepared=ref<Item|null>(null);const loading=ref(false);const busy=ref(false);const polling=ref(false);const uncertain=ref(false);const error=ref('');const clock=ref(Date.now());const nameInput=ref<HTMLInputElement|null>(null);const guard=createRequestGuard();const fieldPrefix='variable-'+crypto.randomUUID();let requestId=crypto.randomUUID();let timer:ReturnType<typeof setInterval>|undefined;let completionSent=false;
const editing=computed(()=>!!props.resource);const previous=computed<Item|null>(()=>options.value?.variable??null);
const pending=computed(()=>review.value?.status==='pending'&&new Date(review.value.expires_at).getTime()>clock.value);
const running=computed(()=>['approved','executing'].includes(review.value?.status));
const result=computed<Item>(()=>review.value?.payload?.execution?.result??{});
const verified=computed(()=>review.value?.status==='completed'&&result.value.configuration_verified===true&&result.value.resource==='variables'&&result.value.variable_key===key.value);
const overridesChanged=computed(()=>!editing.value||overrides.value.some(row=>row.replace||!row.existing)||JSON.stringify(overrides.value.map(row=>Number(row.agent)))!==JSON.stringify((previous.value?.agent_overrides??[]).map((row:Item)=>row.agent_id)));
const patch=computed(()=>{const data:Item={};if(!editing.value||secret.value!==previous.value?.is_secret)data.is_secret=secret.value;if(!editing.value||description.value!==(previous.value?.description??'')){const text=description.value.trim();if(!editing.value||text!==(previous.value?.description??''))data.description=text||null;}if(replaceValue.value)data.value=value.value;if(overridesChanged.value)data.agent_overrides=overrides.value.map(row=>({agent_id:Number(row.agent),...((!row.existing||row.replace)?{value:row.value}:{})}));return data;});
const valid=computed(()=>!!options.value&&/^[A-Z_][A-Z0-9_]{0,255}$/.test(key.value.trim())&&Object.keys(patch.value).length>0&&value.value.length<=65536&&description.value.length<=4000&&overrides.value.length<=32&&overrides.value.every(row=>/^[1-9][0-9]*$/.test(row.agent)&&row.value.length<=65536)&&new Set(overrides.value.map(row=>row.agent)).size===overrides.value.length);
function clearValues(){value.value='';for(const row of overrides.value)row.value='';prepared.value=null;}
async function load(){
 const current=guard.next();clearValues();loading.value=true;busy.value=false;polling.value=false;uncertain.value=false;error.value='';options.value=null;review.value=null;completionSent=false;requestId=crypto.randomUUID();
 try{const data=await props.request(`/catalog/${props.tenant}/variables/${props.resource?props.resource.id+'/configuration':'options'}`);if(!current())return;if(!/^[a-f0-9]{64}$/.test(data.version??'')||!Array.isArray(data.agents)||(props.resource&&data.variable?.id!==props.resource.id))throw new Error('A configuração recebida não corresponde a esta variável. Tente novamente.');options.value=data;key.value=data.variable?.key??'';description.value=data.variable?.description??'';secret.value=data.variable?.is_secret??true;replaceValue.value=!editing.value;overrides.value=(data.variable?.agent_overrides??[]).map((row:Item)=>({id:crypto.randomUUID(),agent:String(row.agent_id),existing:true,replace:false,value:''}));await nextTick();if(current())nameInput.value?.focus();}
 catch(e){if(current())error.value=(e as Error).message;}finally{if(current())loading.value=false;}
}
function addOverride(){if(overrides.value.length<32)overrides.value.push({id:crypto.randomUUID(),agent:'',existing:false,replace:true,value:''});}
async function prepare(){
 if(busy.value||loading.value||(!prepared.value&&!valid.value))return;const current=guard.current();busy.value=true;error.value='';const submitted:Item=prepared.value??{action:editing.value?'update_variable':'create_variable',request_id:requestId,version:options.value!.version,key:key.value.trim(),...JSON.parse(JSON.stringify(patch.value))};prepared.value=submitted;
 try{const response=await props.request(`/catalog/${props.tenant}/variables/actions`,'POST',submitted);if(!current())return;if(typeof response.approval?.id!=='string'||response.approval.payload?.action?.key!==submitted.key||typeof response.approval?.status!=='string')throw new Error('Não foi possível confirmar a revisão desta variável. Consulte a mesma solicitação.');review.value=response.approval;key.value=submitted.key;clearValues();emit('updated');}
 catch(e){if(current())error.value=(e as Error).message;}finally{if(current())busy.value=false;}
}
function notifyCompletion(){if(!verified.value||completionSent)return;completionSent=true;emit('updated');emit('notice',result.value.message);}
async function refreshStatus(force=false){
 if(polling.value||!review.value||(!running.value&&!force))return;const current=guard.current();const id=review.value.id;polling.value=true;
 try{const response=await props.request(`/bi-actions/${id}`);if(!current()||review.value?.id!==id)return;if(response.approval?.id!==id)throw new Error('A consulta não retornou a mesma solicitação. Confira Atividade.');review.value=response.approval;uncertain.value=false;error.value='';notifyCompletion();}
 catch(e){if(current())error.value=(e as Error).message;}finally{if(current())polling.value=false;}
}
async function decide(decision:'approved'|'rejected'){
 if(!pending.value||!review.value||busy.value||uncertain.value)return;const current=guard.current();const id=review.value.id;busy.value=true;error.value='';
 try{const response=await props.request(`/approvals/${id}/decide`,'POST',{decision,fingerprint:review.value.fingerprint});if(!current()||review.value?.id!==id)return;if(response.id!==id)throw new Error('A decisão não retornou a mesma solicitação. Confira seu estado antes de continuar.');review.value=response;emit('updated');if(decision==='approved')await refreshStatus();}
 catch(e){if(current()){uncertain.value=true;error.value='Não foi possível confirmar a decisão. Use Conferir solicitação antes de decidir novamente.';}}finally{if(current())busy.value=false;}
}
function recovered(response:Item){review.value=response.approval;notifyCompletion();}
watch(()=>[props.tenant,props.resource?.id],()=>load());
onMounted(()=>{load();timer=setInterval(()=>{clock.value=Date.now();if(!document.hidden)refreshStatus();},2200);});
onUnmounted(()=>{guard.invalidate();clearValues();if(timer)clearInterval(timer);});
</script>
<template><section class="variable-form" aria-label="Configuração de variável" data-tour="variable-form"><header><span class="project-icon blue"><Tag :size="22"/></span><div><h2>{{editing?'Editar variável':'Adicionar variável'}}</h2><p>{{tenantName}} · Valores reutilizáveis para os recursos deste ambiente.</p></div></header><div v-if="loading" class="variable-loading" role="status"><LoaderCircle :size="23" class="spin"/><p>Conferindo a configuração atual e os agentes…</p></div><template v-else-if="!review"><form v-if="options" autocomplete="off" @submit.prevent="prepare"><fieldset :disabled="busy||!!prepared"><div class="variable-field"><label :for="fieldPrefix+'-key'">Nome da variável</label><input :id="fieldPrefix+'-key'" ref="nameInput" v-model="key" :disabled="editing" required maxlength="256" pattern="[A-Z_][A-Z0-9_]*" placeholder="Ex.: JANELA_CARGA_DIAS" autocomplete="off" autocapitalize="characters" :spellcheck="false"><small>Use letras maiúsculas, números e _. A primeira posição não pode ser um número. {{editing?'O nome não é alterado nesta edição.':'Escolha um identificador para reutilizar nos recursos do tenant.'}}</small></div><div class="variable-field"><label :for="fieldPrefix+'-description'">Para que serve esta variável? <span>opcional</span></label><textarea :id="fieldPrefix+'-description'" v-model="description" rows="2" maxlength="4000" placeholder="Ex.: Quantos dias serão consultados na carga"></textarea></div><label class="variable-check"><input v-model="secret" type="checkbox">Proteger o valor como segredo no BI</label><p class="variable-hint">Segredos não são devolvidos pelo BI. Os valores já cadastrados, mesmo comuns, não são exibidos neste formulário nem enviados à IA.</p><label v-if="editing" class="variable-check"><input v-model="replaceValue" type="checkbox">Substituir valor padrão</label><div v-if="replaceValue" class="variable-field"><label :for="fieldPrefix+'-value'">{{editing?'Novo valor padrão':'Valor padrão'}}</label><textarea :id="fieldPrefix+'-value'" v-model="value" rows="3" maxlength="65536" autocomplete="off" autocapitalize="off" :spellcheck="false" placeholder="Informe o valor que será usado pelos agentes sem uma definição própria"></textarea><small>Espaços e quebras de linha serão mantidos. Deixar vazio define um valor vazio.</small></div><p v-if="editing&&previous?.is_secret" class="variable-hint">Mudanças externas apenas no valor de um segredo não aparecem na comparação. Preencha um novo valor somente quando quiser substituí-lo.</p><details class="variable-overrides" :open="overrides.length>0"><summary>Valores por agente <span>opcional · {{overrides.length}}</span></summary><p>Defina um valor diferente para um agente específico. Os demais usam o valor padrão. Remover uma definição faz esse agente voltar ao padrão.</p><p v-if="options.agents_message" class="variable-hint">{{options.agents_message}}</p><article v-for="(row,index) in overrides" :key="row.id"><div class="variable-override-heading"><label :for="fieldPrefix+'-agent-'+row.id">Agente {{index+1}}</label><button class="icon-button" type="button" :aria-label="'Remover definição '+(row.agent?'do agente '+row.agent:'por agente')" @click="overrides.splice(index,1)"><Trash2 :size="16"/></button></div><select :id="fieldPrefix+'-agent-'+row.id" v-model="row.agent" :disabled="row.existing" required><option value="">Escolha um agente</option><option v-if="row.existing&&!options.agents.some((agent:Item)=>String(agent.id)===row.agent)" :value="row.agent">Agente #{{row.agent}} · definição atual</option><option v-for="agent in options.agents" :key="agent.id" :value="String(agent.id)">{{agent.name}}</option></select><label v-if="row.existing" class="variable-check"><input v-model="row.replace" type="checkbox">Substituir valor deste agente</label><div v-if="row.replace||!row.existing" class="variable-field"><label :for="fieldPrefix+'-override-'+row.id">Novo valor do agente</label><textarea :id="fieldPrefix+'-override-'+row.id" v-model="row.value" rows="2" maxlength="65536" autocomplete="off" autocapitalize="off" :spellcheck="false"></textarea></div><small v-else>O valor já cadastrado será mantido.</small></article><button class="secondary-button" type="button" :disabled="overrides.length>=32||!options.agents.length" @click="addOverride"><Plus :size="15"/>Adicionar valor por agente</button></details></fieldset><p class="variable-privacy"><LockKeyhole :size="16"/>A revisão mostra a configuração e o efeito da alteração. Os valores ficam protegidos e não aparecem na revisão técnica.</p><p v-if="error" class="form-error" role="alert"><AlertCircle :size="16"/>{{error}}</p><p v-if="prepared&&!busy" class="variable-hint">A solicitação mantém os mesmos valores para uma consulta segura. Reabrir a configuração descarta os campos digitados e prepara outra revisão.</p><footer><button class="secondary-button" type="button" :disabled="busy" @click="emit('close')">Cancelar</button><button v-if="prepared&&!busy" class="secondary-button" type="button" @click="load">Reabrir configuração</button><button class="primary-button" :disabled="busy||(!prepared&&!valid)"><LoaderCircle v-if="busy" class="spin" :size="15"/><ShieldCheck v-else :size="15"/>{{prepared?'Consultar mesma solicitação':'Conferir configuração'}}</button></footer></form><template v-else><p v-if="error" class="form-error" role="alert">{{error}}</p><footer><button class="secondary-button" @click="emit('close')">Fechar</button><button class="primary-button" @click="load">Tentar novamente</button></footer></template></template><template v-else><template v-if="pending"><h3>Confira antes de autorizar</h3><ApprovalReview :approval="review" :tenants="[{id:tenant,name:tenantName}]"/><p v-if="error" class="form-error" role="alert">{{error}}</p><footer v-if="uncertain"><button class="secondary-button" :disabled="polling" @click="refreshStatus(true)"><RefreshCw :size="15"/>Conferir solicitação</button></footer><footer v-else><button class="secondary-button" :disabled="busy" @click="decide('rejected')"><X :size="15"/>Recusar</button><button class="primary-button" :disabled="busy" @click="decide('approved')"><Check :size="15"/>{{editing?'Autorizar alteração':'Autorizar criação'}}</button></footer></template><div v-else-if="running" class="variable-result" role="status"><LoaderCircle class="spin" :size="22"/><div><strong>{{review.status==='approved'?'Aguardando execução':'Salvando no BI'}}</strong><p>Os valores serão usados somente nesta operação. Acompanhe também em Atividade.</p></div></div><div v-else-if="verified" class="variable-result success" role="status"><CheckCircle2 :size="23"/><div><strong>Variável configurada</strong><p>{{result.variable_key}}</p><p>{{result.message}}</p><button class="primary-button" @click="emit('saved',result.variable_key)">Ver variável no catálogo</button></div></div><template v-else><div class="variable-result attention" role="alert"><AlertCircle :size="22"/><div><strong>{{review.status==='rejected'?'Revisão recusada':review.status==='expired'?'Revisão expirada':'Esta configuração precisa de conferência'}}</strong><p>{{review.payload?.execution?.message??(review.status==='rejected'?'Os valores privados desta revisão foram descartados.':'Reabra a configuração atual antes de preparar outra alteração.') }}</p></div></div><VariableRecovery :approval="review" :request="request" @confirmed="recovered"/></template><p v-if="error&&!pending" class="form-error" role="alert">{{error}}</p><footer v-if="!pending"><button v-if="!running&&!verified" class="secondary-button" @click="load">Reabrir configuração atual</button><button class="secondary-button" @click="emit('close')">Fechar</button></footer></template></section></template>
<style scoped>.variable-form{color:#365070}.variable-form>header{display:flex;align-items:flex-start;gap:14px;margin-bottom:20px}.variable-form h2{font-size:21px;color:#263e60;margin:0 0 7px}.variable-form h3{font-size:15px;color:#2b466d}.variable-form header p,.variable-hint,.variable-overrides>p{font-size:12px;line-height:1.8;color:#7286a3}.variable-form fieldset{border:0;padding:0;margin:0;min-width:0}.variable-field{margin:17px 0}.variable-field label,.variable-override-heading label{display:block;font-size:12px;font-weight:600;color:#3c567c;margin-bottom:7px}.variable-field label span,.variable-overrides summary span{font-weight:400;color:#8798af}.variable-form input:not([type=checkbox]),.variable-form select,.variable-form textarea{display:block;width:100%;background:#fff;color:#294564}.variable-form textarea{resize:vertical;min-height:60px;max-height:220px}.variable-field small,.variable-overrides article>small{display:block;font-size:11px;line-height:1.7;color:#8494aa;margin-top:7px}.variable-check{display:flex;align-items:flex-start;gap:9px;font-size:12px;font-weight:600;color:#426084;margin:14px 0 7px}.variable-check input{width:16px;height:16px;flex-shrink:0;margin-top:1px}.variable-privacy{display:flex;align-items:flex-start;gap:9px;padding:12px;background:#f0f6ff;border-radius:8px;font-size:11px;line-height:1.8;color:#617b9e;margin-top:19px}.variable-privacy svg{flex-shrink:0;margin-top:2px}.variable-overrides{margin-top:20px;padding:14px;border:1px solid #dce7f5;border-radius:9px}.variable-overrides summary{font-size:12px;font-weight:600;color:#3a5c8b;cursor:pointer}.variable-overrides article{padding:13px;background:#f6f9fd;border:1px solid #dfe8f5;border-radius:8px;margin:13px 0}.variable-override-heading{display:flex;justify-content:space-between;align-items:center;gap:8px}.variable-override-heading label{margin:0}.variable-loading{text-align:center;padding:30px 15px;color:#8092ae;font-size:12px}.variable-loading svg{margin:0 auto 12px}.variable-result{display:flex;align-items:flex-start;gap:12px;padding:16px;background:#f3f8ff;border:1px solid #dce8f7;border-radius:9px;color:#40628e}.variable-result>svg{flex-shrink:0}.variable-result strong{font-size:14px}.variable-result p{font-size:12px;line-height:1.8;margin:8px 0 13px;overflow-wrap:anywhere}.variable-result.success{background:#f4fbf7;border-color:#d0e7db;color:#2a7454}.variable-result.attention{background:#fff9f1;border-color:#eedec8;color:#875d2e}.variable-form footer{display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap;margin-top:22px}.variable-form .form-error{margin:15px 0}@media(max-width:600px){.variable-form h2{font-size:19px}.variable-form footer>button{width:100%}.variable-form input:not([type=checkbox]),.variable-form select,.variable-form textarea{font-size:16px}.variable-overrides{padding:10px}.variable-overrides article{padding:10px}}</style>
